/**
 * @typedef {Object} HTTPTiming
 * @property {number} startTime - Request start timestamp (milliseconds)
 * @property {number} endTime - Request end timestamp (milliseconds)
 * @property {number} duration - Request duration (milliseconds)
 * @property {Object} [phases] - Optional detailed timing phases
 */

/**
 * @typedef {Object} HTTPExchangeWithTiming
 * @property {Object} request - HTTP request data
 * @property {Object} response - HTTP response data
 * @property {HTTPTiming} timing - Timing information
 */

/**
 * What each Resource Timing initiator means: [short label, explanation]
 * @const {Object<string, string[]>}
 */
const INITIATOR_INFO = {
  navigation: ['doc', 'The document itself: the URL that was navigated to'],
  link: ['link', 'Requested by a <link> element, such as a stylesheet or a preload'],
  script: ['script', 'Requested by a <script> element'],
  img: ['img', 'Requested by an <img> element'],
  image: ['image', 'Requested by an SVG <image> element'],
  css: ['css', 'Requested from inside a stylesheet, such as a font or a background image'],
  iframe: ['iframe', 'A document loaded into an <iframe>'],
  fetch: ['fetch', 'Requested by script with fetch()'],
  xmlhttprequest: ['xhr', 'Requested by script with XMLHttpRequest'],
  beacon: ['beacon', 'Sent by script with navigator.sendBeacon()'],
  video: ['video', 'Requested by a <video> element'],
  audio: ['audio', 'Requested by an <audio> element'],
  other: ['other', 'Requested by the browser itself, such as the favicon'],
};

/**
 * Timing phases in the order they happen: [key, label]
 * @const {string[][]}
 */
const PHASES = [
  ['queue', 'Queued'],
  ['dns', 'DNS'],
  ['connect', 'Connect'],
  ['tls', 'TLS'],
  ['wait', 'Waiting'],
  ['download', 'Download'],
];

const CACHE_TEXT = {
  network: 'fetched over the network',
  cache: 'served from cache; nothing was sent',
  revalidated: 'revalidated; the server answered 304 and the cached body was reused',
  unknown: 'not exposed',
};

/**
 * HTTPWaterfallElement - Web component for displaying multiple HTTP exchanges
 * Supports list, duration, and waterfall timeline views with live capture capability
 *
 * @class
 * @extends HTMLElement
 *
 * @example
 * // Static data display
 * const waterfall = document.querySelector('http-waterfall');
 * waterfall.exchanges = [
 *   {
 *     request: { method: 'GET', url: '/api/users' },
 *     response: { status: 200, statusText: 'OK' },
 *     timing: { startTime: 0, endTime: 87, duration: 87 }
 *   }
 * ];
 *
 * @example
 * // Live capture mode
 * <http-waterfall capture="true" filter="/api/*" theme="dark"></http-waterfall>
 *
 * @example
 * // Page-load mode: every request the page itself made, from Resource Timing
 * <http-waterfall resources></http-waterfall>
 */
class HTTPWaterfallElement extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this._exchanges = [];
    this._view = 'duration'; // 'list', 'duration', or 'waterfall'
    this._expandedRows = new Set();
    this._capture = false;
    this._filter = null;
    this._maxEntries = 100;
    this._isPaused = false;
    this._interceptor = null;
    this._resources = false;
    this._resourceSource = null;

    // Explorer (request builder) state
    this._explorerOpen = false;
    this._explorerHeaders = [{ name: '', value: '' }];
    this._explorerLoading = false;
    this._explorerStatus = null;

    // Handle property shadowing like http-console
    if (this.hasOwnProperty('exchanges')) {
      const existingData = this.exchanges;
      delete this.exchanges;
      this.exchanges = existingData;
    }
  }

  static get observedAttributes() {
    return [
      'view',
      'requests',
      'capture',
      'resources',
      'filter',
      'max-entries',
      'theme',
      'explorer',
    ];
  }

  /**
   * Called when element is added to the DOM
   * @memberof HTTPWaterfallElement
   */
  connectedCallback() {
    // Set smart default view if not explicitly set
    if (!this.hasAttribute('view')) {
      this._view = this.getSmartDefaultView();
    }

    // Check if explorer should be open initially
    this._explorerOpen = this.hasAttribute('explorer');

    // Create initial DOM structure
    this.shadowRoot.innerHTML = `
      <style>${HTTP_WATERFALL_STYLES}</style>
      <div class="http-waterfall">
        <div class="toolbar-container"></div>
        <div class="explorer-container"></div>
        <div class="view-container"></div>
      </div>
    `;

    // Cache container references
    this._toolbarContainer = this.shadowRoot.querySelector('.toolbar-container');
    this._explorerContainer = this.shadowRoot.querySelector('.explorer-container');
    this._viewContainer = this.shadowRoot.querySelector('.view-container');

    // Initial render
    this.renderToolbar();
    this.renderExplorer();
    this.renderView();
    this.updateTheme();

    // Start capturing if enabled
    if (this._capture) {
      this.startCapture();
    }

    // Start listing the page's own requests if enabled
    if (this._resources) {
      this.startResources();
    }
  }

  disconnectedCallback() {
    // Stop capturing when component is removed
    this.stopCapture();
    this.stopResources();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue !== newValue) {
      if (name === 'view') {
        this._view = newValue || 'list';
      } else if (name === 'requests') {
        try {
          this._exchanges = JSON.parse(newValue) || [];
        } catch (e) {
          console.error('Failed to parse requests:', e);
        }
      } else if (name === 'capture') {
        this._capture = newValue === 'true' || newValue === '';
        if (this._capture && this.isConnected) {
          this.startCapture();
        } else {
          this.stopCapture();
        }
      } else if (name === 'resources') {
        this._resources = newValue !== null && newValue !== 'false';
        // During upgrade the attributes arrive one at a time, before
        // connectedCallback. Wait for it, so filter and max-entries are read
        // before the first entries are delivered.
        if (this._resources && this._viewContainer) {
          this.startResources();
        } else {
          this.stopResources();
        }
        this.renderExplorer();
      } else if (name === 'filter') {
        this._filter = newValue;
        if (this._interceptor) {
          this._interceptor.filter = newValue;
        }
        if (this._resourceSource) {
          this._resourceSource.filter = newValue;
        }
      } else if (name === 'max-entries') {
        this._maxEntries = parseInt(newValue, 10) || 100;
      } else if (name === 'theme') {
        this.updateTheme();
        return; // Don't re-render for theme changes
      } else if (name === 'explorer') {
        this._explorerOpen = newValue !== null;
        this.renderExplorer();
        return; // Don't re-render everything for explorer toggle
      }
      this.render();
    }
  }

  /**
   * Update theme based on attribute or system preference
   */
  updateTheme() {
    const themeAttr = this.getAttribute('theme');

    if (themeAttr === 'dark' || themeAttr === 'light') {
      // Explicit theme set
      this.setAttribute('theme', themeAttr);
    } else if (themeAttr === 'auto' || !themeAttr) {
      // Auto-detect from system preferences
      const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      this.setAttribute('theme', prefersDark ? 'dark' : 'light');
    }

    // Also update any http-console children
    this.updateChildThemes();
  }

  /**
   * Update theme on child http-transaction/http-console elements
   */
  updateChildThemes() {
    const theme = this.getAttribute('theme');
    // Support both http-transaction (new) and http-console (backwards compat)
    const transactions = this.shadowRoot.querySelectorAll('http-transaction, http-console');
    transactions.forEach(el => {
      el.setAttribute('theme', theme);
    });
  }

  /**
   * Set HTTP exchanges to display
   * @param {HTTPExchangeWithTiming[]} value - Array of HTTP exchanges with timing
   * @memberof HTTPWaterfallElement
   */
  set exchanges(value) {
    this._exchanges = Array.isArray(value) ? value : [];
    this.render();
  }

  /**
   * Get current HTTP exchanges
   * @returns {HTTPExchangeWithTiming[]} Array of exchanges
   * @memberof HTTPWaterfallElement
   */
  get exchanges() {
    return this._exchanges;
  }

  /**
   * Set current view mode
   * @param {'list'|'duration'|'waterfall'} value - View mode
   * @memberof HTTPWaterfallElement
   */
  set view(value) {
    if (this._view !== value) {
      this._view = value;
      // Re-render both toolbar (to update active button) and view
      this.renderToolbar();
      this.renderView();
    }
  }

  /**
   * Get current view mode
   * @returns {'list'|'duration'|'waterfall'} Current view mode
   * @memberof HTTPWaterfallElement
   */
  get view() {
    return this._view;
  }

  /**
   * Start capturing live HTTP requests using the interceptor
   * @memberof HTTPWaterfallElement
   */
  startCapture() {
    if (this._interceptor) return; // Already capturing

    this._interceptor = new HTTPInterceptor();
    this._interceptor.start(
      exchange => {
        this.addCapturedExchange(exchange);
      },
      {
        filter: this._filter,
      }
    );
  }

  /**
   * Stop capturing
   */
  stopCapture() {
    if (this._interceptor) {
      this._interceptor.stop();
      this._interceptor = null;
    }
  }

  /**
   * Start listing the requests the page itself made, from the browser's
   * Navigation Timing and Resource Timing data: the document, stylesheets,
   * scripts, images, fonts, and frames, oldest first. Requests that finish
   * later (a lazy image, a late font) are added as they complete.
   * @memberof HTTPWaterfallElement
   */
  startResources() {
    if (this._resourceSource) return; // Already listing

    // A page load reads as a timeline unless a view was asked for
    if (!this.hasAttribute('view') && this._view !== 'waterfall') {
      this._view = 'waterfall';
      this.renderToolbar();
    }

    this._resourceSource = new ResourceTimingSource();
    this._resourceSource.start(exchanges => this.addResourceExchanges(exchanges), {
      filter: this._filter,
      // The interceptor already reports fetch and XHR, with headers and bodies
      skipScripted: this._capture,
    });
  }

  /**
   * Stop listing the page's own requests
   * @memberof HTTPWaterfallElement
   */
  stopResources() {
    if (this._resourceSource) {
      this._resourceSource.stop();
      this._resourceSource = null;
    }
  }

  /**
   * Add a batch of exchanges built from Resource Timing entries
   * @param {HTTPExchangeWithTiming[]} exchanges - Exchanges to add
   */
  addResourceExchanges(exchanges) {
    this.insertChronological(exchanges);
    this.dispatchEvent(new CustomEvent('resources-observed', { detail: { exchanges } }));
  }

  /**
   * Merge exchanges into the list in start-time order, oldest first
   * @param {HTTPExchangeWithTiming[]} exchanges - Exchanges to merge
   */
  insertChronological(exchanges) {
    const merged = this._exchanges.concat(exchanges);
    merged.sort((a, b) => (a.timing?.startTime || 0) - (b.timing?.startTime || 0));
    this._exchanges = merged.slice(0, this._maxEntries);
    this.renderView();
    this.updateRequestCount();
  }

  /**
   * True when an exchange carries usable timing. A start time of 0 is valid:
   * the document itself starts at 0.
   * @param {HTTPExchangeWithTiming} exchange - Exchange to test
   * @returns {boolean} Whether the exchange can be placed on a timeline
   */
  hasTiming(exchange) {
    const timing = exchange.timing;
    return !!timing && Number.isFinite(timing.startTime) && timing.endTime > 0;
  }

  /**
   * Pause/resume capturing
   */
  togglePause() {
    if (!this._interceptor) return;

    this._isPaused = !this._isPaused;
    if (this._isPaused) {
      this._interceptor.pause();
    } else {
      this._interceptor.resume();
    }
    // Only re-render toolbar to update pause button and indicator
    this.renderToolbar();
  }

  /**
   * Clear all captured exchanges
   */
  clearExchanges() {
    this._exchanges = [];
    this._expandedRows.clear();
    // Update view and request count
    this.renderView();
    this.updateRequestCount();
  }

  /**
   * Determine if requests are clustered (within 10 seconds of each other)
   */
  areRequestsClustered() {
    if (this._exchanges.length < 2) return false;

    const times = this._exchanges.filter(e => this.hasTiming(e)).map(e => e.timing.startTime);

    if (times.length === 0) return false;

    const min = Math.min(...times);
    const max = Math.max(...times);

    // Clustered if all requests within 10 seconds
    return max - min < 10000;
  }

  /**
   * Get smart default view based on context
   */
  getSmartDefaultView() {
    // A page load is a timeline
    if (this._resources) {
      return 'waterfall';
    }

    // Live capture always defaults to duration (independent requests)
    if (this._capture) {
      return 'duration';
    }

    // Static data: waterfall if clustered, duration if dispersed
    if (this.areRequestsClustered()) {
      return 'waterfall';
    }

    return 'duration';
  }

  /**
   * Add a captured exchange
   */
  addCapturedExchange(exchange) {
    // Alongside the page's own requests, keep one timeline in start order
    if (this._resources) {
      this.insertChronological([exchange]);
      return;
    }

    // Add to beginning of array (most recent first)
    this._exchanges.unshift(exchange);

    // Limit to max entries
    if (this._exchanges.length > this._maxEntries) {
      this._exchanges = this._exchanges.slice(0, this._maxEntries);
    }

    // Only update the view content, not the toolbar
    this.renderView();

    // Update just the request count in toolbar
    this.updateRequestCount();
  }

  toggleRow(index) {
    if (this._expandedRows.has(index)) {
      this._expandedRows.delete(index);
    } else {
      this._expandedRows.add(index);
    }
    // Only re-render the view content
    this.renderView();
  }

  render() {
    // Only render if connected
    if (!this._toolbarContainer || !this._viewContainer) return;

    this.renderToolbar();
    this.renderView();
  }

  renderView() {
    if (!this._viewContainer) return;

    let view;
    if (this._view === 'waterfall') {
      view = this.renderWaterfallView();
    } else if (this._view === 'duration') {
      view = this.renderDurationView();
    } else {
      view = this.renderListView();
    }

    this._viewContainer.innerHTML = view;

    // Attach event listeners for view (expand buttons)
    this.attachViewEventListeners();
  }

  renderToolbar() {
    if (!this._toolbarContainer) return;

    const captureControls = this._capture
      ? `
      <div class="capture-controls">
        <button class="control-btn pause-btn" title="${this._isPaused ? 'Resume' : 'Pause'}">
          ${this._isPaused ? '▶' : '⏸'}
        </button>
        <button class="control-btn clear-btn" title="Clear all">
          🗑
        </button>
        <span class="capture-indicator ${this._isPaused ? 'paused' : 'active'}">
          ${this._isPaused ? 'Paused' : 'Capturing'}
        </span>
      </div>
    `
      : '';

    this._toolbarContainer.innerHTML = `
      <div class="toolbar">
        <div class="view-toggle">
          <button class="view-btn ${this._view === 'list' ? 'active' : ''}" data-view="list">List</button>
          <button class="view-btn ${this._view === 'duration' ? 'active' : ''}" data-view="duration">Duration</button>
          <button class="view-btn ${this._view === 'waterfall' ? 'active' : ''}" data-view="waterfall">Waterfall</button>
        </div>
        ${captureControls}
        <div class="info">
          ${this.getSummaryText()}
        </div>
      </div>
    `;

    // Attach toolbar event listeners
    this.attachToolbarEventListeners();
  }

  renderListView() {
    if (this._exchanges.length === 0) {
      return '<div class="empty">No requests to display</div>';
    }

    return `
      <div class="list-view">
        ${this._exchanges.map((exchange, index) => this.renderExchangeRow(exchange, index)).join('')}
      </div>
    `;
  }

  renderExchangeRow(exchange, index) {
    const { request, response, timing } = exchange;
    const isExpanded = this._expandedRows.has(index);
    const method = request?.method || '?';
    const url = request?.url || '';
    const status = response?.status || 0;
    const statusText = response?.statusText || '';
    const duration = timing?.duration || 0;

    // Calculate response size (rough estimate from body length)
    const bodySize = response?.body?.length || 0;
    const size = this.formatSize(bodySize);

    const statusClass = this.getStatusClass(status);

    if (exchange.resource) {
      const resource = exchange.resource;
      return `
      <div class="exchange-row ${isExpanded ? 'expanded' : ''}" data-index="${index}" data-initiator="${this.escapeHtml(resource.initiatorType)}" data-cross-origin="${resource.crossOrigin}">
        <div class="exchange-summary resource">
          ${this.renderRowChip(exchange)}
          <span class="url ${resource.crossOrigin ? 'cross-origin' : ''}" title="${this.escapeHtml(url)}">${this.escapeHtml(resource.label)}</span>
          <span class="status ${statusClass}">${status || '—'}</span>
          <span class="size" title="${this.escapeHtml(this.getResourceSizeTitle(resource))}">${this.getResourceSizeLabel(resource)}</span>
          <span class="duration">${duration}ms</span>
          <button class="expand-btn" data-index="${index}">
            ${isExpanded ? '▼' : '▶'}
          </button>
        </div>
        ${isExpanded ? this.renderExchangeDetail(exchange) : ''}
      </div>
    `;
    }

    return `
      <div class="exchange-row ${isExpanded ? 'expanded' : ''}" data-index="${index}">
        <div class="exchange-summary">
          <span class="method method-${method.toLowerCase()}">${method}</span>
          <span class="url" title="${this.escapeHtml(url)}">${this.escapeHtml(url)}</span>
          <span class="status ${statusClass}">${status} ${statusText}</span>
          <span class="size">${size}</span>
          <span class="duration">${duration}ms</span>
          <button class="expand-btn" data-index="${index}">
            ${isExpanded ? '▼' : '▶'}
          </button>
        </div>
        ${isExpanded ? this.renderExchangeDetail(exchange) : ''}
      </div>
    `;
  }

  renderExchangeDetail(exchange) {
    // Resource Timing has no headers or bodies to show in wire format
    if (exchange.resource) {
      return `
      <div class="exchange-detail">
        ${this.renderResourceFacts(exchange)}
      </div>
    `;
    }

    const { request, response } = exchange;
    // Create a unique ID for this detail element
    const detailId = `detail-${Math.random().toString(36).substr(2, 9)}`;

    // Return placeholder that will be populated with http-transaction element
    setTimeout(() => {
      const detailElement = this.shadowRoot.getElementById(detailId);
      if (detailElement) {
        const transactionElement = document.createElement('http-transaction');
        transactionElement.data = { request, response };
        // Apply theme to child transaction
        const theme = this.getAttribute('theme');
        if (theme) {
          transactionElement.setAttribute('theme', theme);
        }
        detailElement.appendChild(transactionElement);
      }
    }, 0);

    return `
      <div class="exchange-detail">
        <div id="${detailId}" class="detail-console-container"></div>
      </div>
    `;
  }

  renderDurationView() {
    if (this._exchanges.length === 0) {
      return '<div class="empty">No requests to display</div>';
    }

    // Get max duration for scaling
    const maxDuration = this.getMaxDuration();

    if (maxDuration === 0) {
      return '<div class="empty">No duration data available</div>';
    }

    return `
      <div class="duration-view">
        <div class="duration-header">
          <div class="request-info-header">Request</div>
          <div class="duration-scale-header">Duration</div>
        </div>
        <div class="duration-rows">
          ${this._exchanges
            .map((exchange, index) => this.renderDurationRow(exchange, index, maxDuration))
            .join('')}
        </div>
      </div>
    `;
  }

  renderDurationRow(exchange, index, maxDuration) {
    const { request, response, timing } = exchange;
    const method = request?.method || '?';
    const url = request?.url || '';
    const status = response?.status || 0;
    const statusText = response?.statusText || '';
    const duration = timing?.duration || 0;
    const isExpanded = this._expandedRows.has(index);

    const statusClass = this.getStatusClass(status);
    const barClass = statusClass || (exchange.resource ? 'status-unknown' : '');
    const tooltip = exchange.resource
      ? this.getResourceTooltip(exchange)
      : `${method} ${url}\nStatus: ${status} ${statusText}\nDuration: ${duration}ms`;

    return `
      <div class="duration-row-container ${isExpanded ? 'expanded' : ''}"${this.renderResourceAttributes(exchange)}>
        <div class="duration-row">
          <div class="request-info">
            ${this.renderRowChip(exchange)}
            ${this.renderShortUrl(exchange)}
            <span class="status ${statusClass}">${status || (exchange.resource ? '—' : status)}</span>
            <button class="expand-btn" data-index="${index}">
              ${isExpanded ? '▼' : '▶'}
            </button>
          </div>
          <div class="duration-bar-area">
            <div class="duration-bar ${barClass}"
                 title="${this.escapeHtml(tooltip)}"
                 style="--duration: ${duration}; --max-duration: ${maxDuration}">
              <span class="duration-label">${duration}ms</span>
            </div>
          </div>
        </div>
        ${isExpanded ? this.renderExchangeDetail(exchange) : ''}
      </div>
    `;
  }

  getMaxDuration() {
    if (this._exchanges.length === 0) return 0;

    const durations = this._exchanges.map(e => e.timing?.duration || 0).filter(d => d > 0);

    return durations.length > 0 ? Math.max(...durations) : 0;
  }

  renderWaterfallView() {
    if (this._exchanges.length === 0) {
      return '<div class="empty">No requests to display</div>';
    }

    // Calculate timing metadata
    const timed = this._exchanges.filter(e => this.hasTiming(e));

    if (timed.length === 0) {
      return '<div class="empty">No timing data available for waterfall view</div>';
    }

    const baseTime = Math.min(...timed.map(e => e.timing.startTime));
    const maxTime = Math.max(...timed.map(e => e.timing.endTime));
    // Never zero: the bars divide by it
    const totalDuration = Math.max(maxTime - baseTime, 1);
    const hasPhases = timed.some(e => e.timing.phases);

    return `
      <div class="waterfall-view">
        ${this.renderTimelineHeader(totalDuration)}
        ${hasPhases ? this.renderPhaseLegend() : ''}
        <div class="waterfall-rows">
          ${this._exchanges
            .map((exchange, index) =>
              this.renderWaterfallRow(exchange, index, baseTime, totalDuration)
            )
            .join('')}
        </div>
      </div>
    `;
  }

  renderTimelineHeader(totalDuration) {
    // Create exactly 5 time markers evenly spaced across the timeline
    const markers = [];
    const positions = [0, 0.25, 0.5, 0.75, 1.0];

    // Bars are drawn across (100% - 32px), inset 16px. Place each marker on
    // the same scale so a label sits over the time it names.
    for (let i = 0; i < positions.length; i++) {
      const time = Math.round(totalDuration * positions[i]);
      const place =
        positions[i] === 1
          ? 'left: auto; right: 16px;'
          : `left: calc(16px + (100% - 32px) * ${positions[i]});`;
      markers.push(`<span class="time-marker" style="${place}">${time}ms</span>`);
    }

    return `
      <div class="timeline-header">
        <div class="request-info-header">Request</div>
        <div class="timeline-scale">${markers.join('')}</div>
      </div>
    `;
  }

  renderWaterfallRow(exchange, index, baseTime, totalDuration) {
    const { request, response, timing } = exchange;
    const method = request?.method || '?';
    const url = request?.url || '';
    const status = response?.status || 0;
    const statusText = response?.statusText || '';
    const duration = timing?.duration || 0;
    const startTime = timing?.startTime || 0;
    const isExpanded = this._expandedRows.has(index);

    // Calculate offset from base time
    const offset = startTime - baseTime;
    const statusClass = this.getStatusClass(status);
    const barClass = statusClass || (exchange.resource ? 'status-unknown' : '');
    const tooltip = exchange.resource
      ? this.getResourceTooltip(exchange)
      : `${method} ${url}\nStatus: ${status} ${statusText}\nStart: ${offset}ms\nDuration: ${duration}ms`;
    const phases = this.renderPhases(exchange);

    return `
      <div class="waterfall-row-container ${isExpanded ? 'expanded' : ''}"${this.renderResourceAttributes(exchange)}>
        <div class="waterfall-row">
          <div class="request-info">
            ${this.renderRowChip(exchange)}
            ${this.renderShortUrl(exchange)}
            <span class="status ${statusClass}">${status || (exchange.resource ? '—' : status)}</span>
            <button class="expand-btn" data-index="${index}">
              ${isExpanded ? '▼' : '▶'}
            </button>
          </div>
          <div class="timing-area">
            <div class="timing-bar ${barClass} ${phases ? 'has-phases' : ''}"
                 title="${this.escapeHtml(tooltip)}"
                 style="--start-offset: ${offset}; --duration: ${duration}; --total-duration: ${totalDuration}">
              ${phases}
              <span class="duration-label">${duration}ms</span>
            </div>
          </div>
        </div>
        ${isExpanded ? this.renderExchangeDetail(exchange) : ''}
      </div>
    `;
  }

  // ===== Resource Timing rendering =====

  /**
   * The chip at the start of a row: the HTTP method, or for a resource
   * exchange, what asked for it
   */
  renderRowChip(exchange) {
    if (!exchange.resource) {
      const method = exchange.request?.method || '?';
      return `<span class="method method-${method.toLowerCase()}">${method}</span>`;
    }

    const type = exchange.resource.initiatorType;
    const [label, meaning] = INITIATOR_INFO[type] || [type, `Requested by: ${type}`];
    return `<span class="method initiator" title="${this.escapeHtml(meaning)}">${this.escapeHtml(label)}</span>`;
  }

  /**
   * The shortened URL for duration and waterfall rows. Resource exchanges
   * show a path, or a host and path when the request left the page's origin.
   */
  renderShortUrl(exchange) {
    const url = exchange.request?.url || '';
    if (!exchange.resource) {
      return `<span class="url-short" title="${this.escapeHtml(url)}">${this.escapeHtml(this.shortenUrl(url))}</span>`;
    }

    const { label, crossOrigin } = exchange.resource;
    return `<span class="url-short ${crossOrigin ? 'cross-origin' : ''}" title="${this.escapeHtml(url)}">${this.escapeHtml(shortenMiddle(label, 28))}</span>`;
  }

  /** Data attributes that let a page style or select resource rows */
  renderResourceAttributes(exchange) {
    if (!exchange.resource) return '';
    const { initiatorType, crossOrigin } = exchange.resource;
    return ` data-initiator="${this.escapeHtml(initiatorType)}" data-cross-origin="${crossOrigin}"`;
  }

  /** Coloured segments inside a waterfall bar, one per timing phase */
  renderPhases(exchange) {
    const phases = exchange.timing?.phases;
    if (!phases) return '';

    const segments = PHASES.filter(([key]) => phases[key] > 0);
    if (segments.length === 0) return '';

    return `<span class="phases" aria-hidden="true">${segments
      .map(([key]) => `<span class="phase phase-${key}" style="--ms: ${phases[key]}"></span>`)
      .join('')}</span>`;
  }

  renderPhaseLegend() {
    return `
      <div class="phase-legend">
        ${PHASES.map(([key, label]) => `<span><i class="phase-${key}"></i>${label}</span>`).join('')}
      </div>
    `;
  }

  /** One line of phase timings, in the order they happen */
  getPhaseText(phases) {
    return (
      PHASES.map(([key, label]) => `${label} ${Math.round(phases[key])}`).join(' · ') + ' (ms)'
    );
  }

  getResourceSizeLabel(resource) {
    if (resource.opaque) return 'hidden';
    if (resource.cache === 'cache') return 'cache';
    if (resource.cache === 'revalidated') return 'revalidated';
    return this.formatBytes(resource.transferSize);
  }

  getResourceSizeTitle(resource) {
    if (resource.opaque) {
      return 'Cross-origin response without Timing-Allow-Origin: sizes are not exposed';
    }
    return `On the wire: ${this.formatBytes(resource.transferSize)}\n${this.getBodyText(resource)}`;
  }

  /** Body size as sent and as decoded, with the saving when it was compressed */
  getBodyText(resource) {
    const { encodedBodySize: sent, decodedBodySize: decoded } = resource;
    let text = `Body: ${this.formatBytes(sent)} sent, ${this.formatBytes(decoded)} decoded`;
    if (sent > 0 && sent < decoded) {
      text += ` (${Math.round((1 - sent / decoded) * 100)}% smaller)`;
    }
    return text;
  }

  getResourceTooltip(exchange) {
    const { request, response, timing, resource } = exchange;
    const [, meaning] = INITIATOR_INFO[resource.initiatorType] || ['', resource.initiatorType];
    const lines = [
      request.url,
      meaning,
      `Status: ${response.status || 'not reported'}${request.httpVersion ? ` over ${request.httpVersion}` : ''}`,
      `Start: ${timing.startTime}ms, duration: ${timing.duration}ms`,
    ];
    if (resource.opaque) {
      lines.push('Sizes and phases hidden: cross-origin without Timing-Allow-Origin');
    } else {
      lines.push(`On the wire: ${this.formatBytes(resource.transferSize)}`);
      lines.push(this.getBodyText(resource));
      lines.push(`Cache: ${CACHE_TEXT[resource.cache]}`);
      if (timing.phases) lines.push(this.getPhaseText(timing.phases));
    }
    return lines.join('\n');
  }

  /** The expanded detail for a resource exchange: what the browser reports */
  renderResourceFacts(exchange) {
    const { request, response, timing, resource } = exchange;
    const [, meaning] = INITIATOR_INFO[resource.initiatorType] || ['', resource.initiatorType];
    const hidden = 'hidden: cross-origin response without Timing-Allow-Origin';

    const facts = [
      ['URL', request.url],
      ['Requested by', meaning],
      ['Origin', resource.crossOrigin ? 'cross-origin' : 'same origin as the page'],
      ['Protocol', request.httpVersion || 'not reported'],
      ['Status', response.status || 'not reported'],
    ];
    if (resource.contentType) facts.push(['Content type', resource.contentType]);
    if (resource.contentEncoding) facts.push(['Content encoding', resource.contentEncoding]);
    facts.push(
      [
        'On the wire',
        resource.opaque ? hidden : `${this.formatBytes(resource.transferSize)} (headers and body)`,
      ],
      ['Body', resource.opaque ? hidden : this.getBodyText(resource).replace('Body: ', '')],
      ['Cache', CACHE_TEXT[resource.cache]]
    );
    if (resource.renderBlocking) facts.push(['Render blocking', resource.renderBlocking]);
    facts.push(
      ['Timing', `starts at ${timing.startTime} ms, takes ${timing.duration} ms`],
      ['Phases', timing.phases ? this.getPhaseText(timing.phases) : hidden]
    );

    return `
      <dl class="resource-facts">
        ${facts.map(([name, value]) => `<dt>${name}</dt><dd>${this.escapeHtml(String(value))}</dd>`).join('')}
      </dl>
      <p class="resource-note">From the browser's Resource Timing data, which reports no headers or bodies. The Network panel in DevTools shows those.</p>
    `;
  }

  /** Request count, plus bytes and cross-origin count when resources are listed */
  getSummaryText() {
    const count = this._exchanges.length;
    let text = `${count} request${count !== 1 ? 's' : ''}`;

    const resources = this._exchanges.filter(e => e.resource).map(e => e.resource);
    if (resources.length > 0) {
      const bytes = resources.reduce((sum, r) => sum + r.transferSize, 0);
      const crossOrigin = resources.filter(r => r.crossOrigin).length;
      text += ` · ${this.formatBytes(bytes)} transferred`;
      if (crossOrigin > 0) text += ` · ${crossOrigin} cross-origin`;
    }
    return text;
  }

  /** Byte count with one decimal for small kilobyte values */
  formatBytes(bytes) {
    if (bytes < 1024) return `${bytes} B`;
    const kb = bytes / 1024;
    if (kb < 1024) return `${kb < 100 ? kb.toFixed(1) : Math.round(kb)} KB`;
    return `${(kb / 1024).toFixed(1)} MB`;
  }

  calculateTimeInterval(totalDuration) {
    // Choose appropriate interval based on total duration
    if (totalDuration <= 500) return 100;
    if (totalDuration <= 1000) return 200;
    if (totalDuration <= 5000) return 500;
    return 1000;
  }

  shortenUrl(url) {
    if (url.length > 40) {
      return url.substring(0, 37) + '...';
    }
    return url;
  }

  getStatusClass(status) {
    if (status >= 200 && status < 300) return 'status-success';
    if (status >= 300 && status < 400) return 'status-redirect';
    if (status >= 400 && status < 500) return 'status-client-error';
    if (status >= 500) return 'status-server-error';
    return '';
  }

  formatSize(bytes) {
    if (bytes === 0) return '0 B';
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return Math.round(bytes / 1024) + ' KB';
    return Math.round(bytes / (1024 * 1024)) + ' MB';
  }

  escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  /**
   * Update just the request count without re-rendering toolbar
   */
  updateRequestCount() {
    const infoElement = this.shadowRoot.querySelector('.info');
    if (infoElement) {
      infoElement.textContent = this.getSummaryText();
    }
  }

  attachToolbarEventListeners() {
    // View toggle buttons
    const viewBtns = this.shadowRoot.querySelectorAll('.view-btn');
    viewBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        this.view = btn.dataset.view;
      });
    });

    // Pause/Resume button
    const pauseBtn = this.shadowRoot.querySelector('.pause-btn');
    if (pauseBtn) {
      pauseBtn.addEventListener('click', () => {
        this.togglePause();
      });
    }

    // Clear button
    const clearBtn = this.shadowRoot.querySelector('.clear-btn');
    if (clearBtn) {
      clearBtn.addEventListener('click', () => {
        if (confirm('Clear all captured requests?')) {
          this.clearExchanges();
        }
      });
    }
  }

  attachViewEventListeners() {
    // Expand/collapse buttons (only in list view)
    const expandBtns = this.shadowRoot.querySelectorAll('.expand-btn');
    expandBtns.forEach(btn => {
      btn.addEventListener('click', e => {
        e.stopPropagation();
        const index = parseInt(btn.dataset.index, 10);
        this.toggleRow(index);
      });
    });
  }

  // ===== Explorer (Request Builder) Methods =====

  /**
   * Toggle the explorer panel open/closed
   */
  toggleExplorer() {
    this._explorerOpen = !this._explorerOpen;
    this.renderExplorer();
  }

  /**
   * Render the explorer/request builder panel
   */
  renderExplorer() {
    if (!this._explorerContainer) return;

    // A page-load listing has no use for the request builder unless asked for
    if (this._resources && !this.hasAttribute('explorer')) {
      this._explorerContainer.innerHTML = '';
      return;
    }

    this._explorerContainer.innerHTML = `
      <div class="explorer-panel">
        <button class="explorer-toggle ${this._explorerOpen ? 'active' : ''}">
          ${this._explorerOpen ? '\u25BC' : '\u25B6'} Request Builder
        </button>
        <div class="explorer-content ${this._explorerOpen ? 'visible' : ''}">
          ${this.renderExplorerContent()}
        </div>
      </div>
    `;

    this.attachExplorerEventListeners();
  }

  /**
   * Render the explorer form content
   * @returns {string} HTML content
   */
  renderExplorerContent() {
    const statusHtml = this._explorerStatus
      ? `<div class="explorer-status ${this._explorerStatus.type}">${this._explorerStatus.message}</div>`
      : '';

    return `
      <div class="request-builder">
        <div class="request-line-builder">
          <select class="method-select" id="explorer-method">
            <option value="GET">GET</option>
            <option value="POST">POST</option>
            <option value="PUT">PUT</option>
            <option value="PATCH">PATCH</option>
            <option value="DELETE">DELETE</option>
            <option value="HEAD">HEAD</option>
            <option value="OPTIONS">OPTIONS</option>
          </select>
          <input type="text" class="url-input" id="explorer-url" placeholder="https://api.example.com/endpoint" />
          <button class="send-button" id="explorer-send" ${this._explorerLoading ? 'disabled' : ''}>
            ${this._explorerLoading ? 'Sending...' : 'Send'}
          </button>
        </div>

        <div class="headers-section">
          <div class="section-label">Headers</div>
          <div class="headers-list" id="explorer-headers">
            ${this._explorerHeaders.map((h, i) => this.renderHeaderRow(h, i)).join('')}
          </div>
          <button class="add-header-btn" id="explorer-add-header">+ Add Header</button>
        </div>

        <div class="body-section">
          <div class="section-label">Request Body</div>
          <textarea class="body-textarea" id="explorer-body" placeholder="Enter request body (JSON, XML, etc.)"></textarea>
        </div>

        ${statusHtml}
      </div>
    `;
  }

  /**
   * Render a single header row
   * @param {Object} header - Header object with name and value
   * @param {number} index - Row index
   * @returns {string} HTML content
   */
  renderHeaderRow(header, index) {
    return `
      <div class="header-row" data-index="${index}">
        <input type="text" class="header-input name" placeholder="Header name" value="${this.escapeHtml(header.name)}" data-index="${index}" />
        <input type="text" class="header-input value" placeholder="Header value" value="${this.escapeHtml(header.value)}" data-index="${index}" />
        <button class="remove-header-btn" data-index="${index}">\u00D7</button>
      </div>
    `;
  }

  /**
   * Attach event listeners for the explorer panel
   */
  attachExplorerEventListeners() {
    const toggleBtn = this.shadowRoot.querySelector('.explorer-toggle');
    if (toggleBtn) {
      toggleBtn.addEventListener('click', () => this.toggleExplorer());
    }

    const sendBtn = this.shadowRoot.querySelector('#explorer-send');
    if (sendBtn) {
      sendBtn.addEventListener('click', () => this.sendExplorerRequest());
    }

    const addHeaderBtn = this.shadowRoot.querySelector('#explorer-add-header');
    if (addHeaderBtn) {
      addHeaderBtn.addEventListener('click', () => this.addExplorerHeader());
    }

    const headersList = this.shadowRoot.querySelector('#explorer-headers');
    if (headersList) {
      headersList.addEventListener('input', e => {
        if (e.target.classList.contains('header-input')) {
          this.updateExplorerHeader(e.target);
        }
      });
      headersList.addEventListener('click', e => {
        if (e.target.classList.contains('remove-header-btn')) {
          this.removeExplorerHeader(parseInt(e.target.dataset.index, 10));
        }
      });
    }
  }

  /**
   * Add a new header row to the explorer
   */
  addExplorerHeader() {
    this._explorerHeaders.push({ name: '', value: '' });
    this.renderExplorer();
  }

  /**
   * Update a header value in the explorer
   * @param {HTMLInputElement} input - Input element
   */
  updateExplorerHeader(input) {
    const index = parseInt(input.dataset.index, 10);
    const field = input.classList.contains('name') ? 'name' : 'value';
    this._explorerHeaders[index][field] = input.value;
  }

  /**
   * Remove a header row from the explorer
   * @param {number} index - Header index
   */
  removeExplorerHeader(index) {
    this._explorerHeaders.splice(index, 1);
    if (this._explorerHeaders.length === 0) {
      this._explorerHeaders.push({ name: '', value: '' });
    }
    this.renderExplorer();
  }

  /**
   * Send the request built in the explorer
   */
  async sendExplorerRequest() {
    const methodSelect = this.shadowRoot.querySelector('#explorer-method');
    const urlInput = this.shadowRoot.querySelector('#explorer-url');
    const bodyTextarea = this.shadowRoot.querySelector('#explorer-body');

    const method = methodSelect.value;
    const url = urlInput.value.trim();
    const bodyText = bodyTextarea.value.trim();

    // Validation
    if (!url) {
      this._explorerStatus = { type: 'error', message: 'Please enter a URL' };
      this.renderExplorer();
      return;
    }

    try {
      new URL(url);
    } catch {
      this._explorerStatus = { type: 'error', message: 'Invalid URL format' };
      this.renderExplorer();
      return;
    }

    // Build headers object
    const headers = {};
    this._explorerHeaders.forEach(header => {
      if (header.name && header.value) {
        headers[header.name] = header.value;
      }
    });

    // Set loading state
    this._explorerLoading = true;
    this._explorerStatus = { type: 'loading', message: 'Sending request...' };
    this.renderExplorer();

    const startTime = performance.now();

    try {
      // Build fetch options
      const options = { method, headers };

      // Add body for methods that support it
      if (['POST', 'PUT', 'PATCH'].includes(method) && bodyText) {
        options.body = bodyText;
      }

      // Dispatch event for request sent
      this.dispatchEvent(
        new CustomEvent('request-sent', {
          detail: { method, url, headers, body: bodyText },
        })
      );

      // Send request
      const response = await fetch(url, options);
      const endTime = performance.now();
      const duration = Math.round(endTime - startTime);

      // Extract response data
      const responseHeaders = {};
      response.headers.forEach((value, key) => {
        responseHeaders[key] = value;
      });

      let responseBody = null;
      const contentType = response.headers.get('content-type') || '';

      try {
        if (contentType.includes('application/json')) {
          const json = await response.json();
          responseBody = JSON.stringify(json, null, 2);
        } else {
          responseBody = await response.text();
        }
      } catch {
        responseBody = '[Could not read response body]';
      }

      // Create exchange and add to list
      const exchange = {
        request: {
          method,
          url,
          httpVersion: 'HTTP/1.1',
          headers,
          body: bodyText || null,
        },
        response: {
          status: response.status,
          statusText: response.statusText,
          httpVersion: 'HTTP/1.1',
          headers: responseHeaders,
          body: responseBody,
        },
        timing: {
          startTime,
          endTime,
          duration,
        },
      };

      // Add to exchanges
      this._exchanges.unshift(exchange);
      if (this._exchanges.length > this._maxEntries) {
        this._exchanges = this._exchanges.slice(0, this._maxEntries);
      }

      this._explorerLoading = false;
      this._explorerStatus = {
        type: 'success',
        message: `Request completed in ${duration}ms - ${response.status} ${response.statusText}`,
      };

      // Dispatch event for response received
      this.dispatchEvent(
        new CustomEvent('response-received', {
          detail: exchange,
        })
      );

      this.renderExplorer();
      this.renderView();
      this.updateRequestCount();
    } catch (error) {
      const endTime = performance.now();
      const duration = Math.round(endTime - startTime);

      this._explorerLoading = false;
      this._explorerStatus = {
        type: 'error',
        message: `Request failed: ${error.message}`,
      };

      // Create error exchange
      const exchange = {
        request: {
          method,
          url,
          httpVersion: 'HTTP/1.1',
          headers,
          body: bodyText || null,
        },
        response: {
          status: 0,
          statusText: 'Network Error',
          httpVersion: 'HTTP/1.1',
          headers: {},
          body: JSON.stringify({ error: error.message }),
        },
        timing: {
          startTime,
          endTime,
          duration,
        },
      };

      // Add error exchange to list
      this._exchanges.unshift(exchange);

      // Dispatch error event
      this.dispatchEvent(
        new CustomEvent('request-error', {
          detail: { error: error.message },
        })
      );

      this.renderExplorer();
      this.renderView();
      this.updateRequestCount();
    }
  }
}

// Register the custom element
customElements.define('http-waterfall', HTTPWaterfallElement);

export { HTTPWaterfallElement };
